// Writes src/components/leaflet-lib.ts: Leaflet's code and styles as strings,
// so the map pages carry them inside and open without the internet (before,
// they were fetched from a CDN each time the map opened).
// Run after changing the Leaflet version: `npm run leaflet:inline`.

import { readFileSync, writeFileSync } from 'node:fs';

const root = new URL('..', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1');
const pkg = JSON.parse(readFileSync(`${root}node_modules/leaflet/package.json`, 'utf8'));
const js = readFileSync(`${root}node_modules/leaflet/dist/leaflet.js`, 'utf8').replace(/\n\/\/# sourceMappingURL=.*\s*$/, '\n');
const css = readFileSync(`${root}node_modules/leaflet/dist/leaflet.css`, 'utf8');

// Both go inside <script> and <style> tags, which the text must not close.
for (const [name, text, tag] of [['leaflet.js', js, '</script'], ['leaflet.css', css, '</style']]) {
  if (text.toLowerCase().includes(tag)) throw new Error(`${name} contains ${tag}`);
}

writeFileSync(
  `${root}src/components/leaflet-lib.ts`,
  `// Generated by scripts/inline-leaflet.mjs from leaflet@${pkg.version} (BSD-2-Clause,\n` +
    `// © Volodymyr Agafonkin and contributors). Do not edit.\n\n` +
    `export const LEAFLET_VERSION = ${JSON.stringify(pkg.version)};\n` +
    `export const LEAFLET_CSS = ${JSON.stringify(css)};\n` +
    `export const LEAFLET_JS = ${JSON.stringify(js)};\n`,
);
console.log(`leaflet-lib.ts: leaflet@${pkg.version}, ${Math.round((js.length + css.length) / 1024)} KB`);
